#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 toLocal[4];
    float4x4 toWorld[4];
    float4 bounds[4];
    float4 clarity;
    float4 view;
    float4 anim;
};

constant float kExtent = 1.15;
constant float kHalf = 0.045;
constant float kBevel = 0.018;
constant float kInset = 0.01;

struct VOut { float4 position [[position]]; };

vertex VOut mark_vertex(uint vid [[vertex_id]]) {
    float2 p = float2((vid << 1) & 2, vid & 2);
    VOut o;
    o.position = float4(p * 2.0 - 1.0, 0.0, 1.0);
    return o;
}

constexpr sampler kLinear(filter::linear, address::clamp_to_edge);

static float piece2(texture2d<float> field, int i, float2 p) {
    float2 c = clamp(p, -kExtent, kExtent);
    float2 uv = float2(c.x, -c.y) / (2.0 * kExtent) + 0.5;
    return field.sample(kLinear, uv)[i] + length(p - c);
}

// A slab of the piece's outline with rounded rims.
static float piece3(texture2d<float> field, int i, float3 p) {
    float2 w = float2(piece2(field, i, p.xy) + kBevel, abs(p.z) - kHalf + kBevel);
    return min(max(w.x, w.y), 0.0) + length(max(w, 0.0)) - kBevel;
}

static float3 normal3(texture2d<float> field, int i, float3 p) {
    const float e = 0.003;
    const float2 k = float2(1.0, -1.0);
    return normalize(k.xyy * piece3(field, i, p + k.xyy * e) + k.yyx * piece3(field, i, p + k.yyx * e) +
                     k.yxy * piece3(field, i, p + k.yxy * e) + k.xxx * piece3(field, i, p + k.xxx * e));
}

static float2 grad2(texture2d<float> field, int i, float2 p) {
    const float e = 0.003;
    float2 g = float2(piece2(field, i, p + float2(e, 0)) - piece2(field, i, p - float2(e, 0)),
                      piece2(field, i, p + float2(0, e)) - piece2(field, i, p - float2(0, e)));
    return g / max(length(g), 1e-6);
}

static float2 boxHit(float3 ro, float3 rd, float3 lo, float3 hi) {
    float3 inv = 1.0 / rd;
    float3 a = (lo - ro) * inv, b = (hi - ro) * inv;
    float3 mn = min(a, b), mx = max(a, b);
    return float2(max(max(mn.x, mn.y), mn.z), min(min(mx.x, mx.y), mx.z));
}

static float softbox(float3 d, float3 axis, float3 up, float2 extent, float soft) {
    float c = dot(d, axis);
    if (c <= 0.0) return 0.0;
    float3 right = normalize(cross(up, axis));
    float3 top = cross(axis, right);
    float2 q = abs(float2(dot(d, right), dot(d, top)) / c) - extent;
    return 1.0 - smoothstep(-soft, soft, max(q.x, q.y));
}

// A dark studio: a small hard key up left with a soft spill, a strip overhead, a cool strip on the right,
// a low warm fill, and the band of light that crosses the mark once it has landed.
static float3 env(float3 d, float sweep, float shift) {
    float3 key = normalize(float3(-0.55, 0.65, 0.55));
    float3 c = mix(float3(0.004, 0.004, 0.006), float3(0.02, 0.02, 0.028), saturate(d.y * 0.5 + 0.5));
    c += 14.0 * softbox(d, key, float3(0, 1, 0), float2(0.14, 0.09), 0.035) * float3(1.0, 0.97, 0.93);
    c += 1.2 * softbox(d, key, float3(0, 1, 0), float2(0.5, 0.35), 0.25) * float3(1.0, 0.97, 0.93);
    c += 3.0 * softbox(d, normalize(float3(0.1, 0.95, 0.25)), float3(0, 0, -1), float2(1.4, 0.06), 0.05) * float3(0.95, 0.95, 1.0);
    c += 2.5 * softbox(d, normalize(float3(0.95, 0.15, -0.05)), float3(0, 1, 0), float2(0.10, 0.9), 0.08) * float3(0.78, 0.84, 1.0);
    c += 0.7 * softbox(d, normalize(float3(0.15, -0.85, 0.45)), float3(0, 0, 1), float2(0.6, 0.2), 0.2) * float3(1.0, 0.82, 0.74);
    if (sweep >= 0.0) {
        float o = mix(-0.24, 0.24, sweep) + shift;
        float band = dot(d, normalize(float3(1.0, -0.8, 0.0))) - o * d.z;
        c += 9.0 * (1.0 - smoothstep(0.002, 0.01, abs(band))) * saturate(d.z);
    }
    return c;
}

struct Shaded { float3 color; float3 base; float face; };

static Shaded shade(constant Uniforms &u, texture2d<float> field, texture2d<float> art, int i, float3 p, float3 rd) {
    float3 nl = normal3(field, i, p);
    float3x3 R = float3x3(u.toWorld[i][0].xyz, u.toWorld[i][1].xyz, u.toWorld[i][2].xyz);
    float3 n = normalize(R * nl);
    float sweep = u.anim.y;

    // The artwork is read a little inside the edge, so a piece never picks up its neighbour's colour.
    float d2 = piece2(field, i, p.xy);
    float2 q = p.xy - grad2(field, i, p.xy) * max(d2 + kInset, 0.0);
    float3 C = art.sample(kLinear, float2(q.x + 1.0, 1.0 - q.y) * 0.5).rgb;

    float face = smoothstep(0.55, 0.95, abs(nl.z));
    float front = saturate(n.z);
    float3 key = normalize(float3(-0.55, 0.65, 0.55));
    float lit = mix(0.42, 1.0, front) + 0.3 * saturate(dot(n, key)) * (1.0 - front);
    float3 body = C * lit * (nl.z < 0.0 ? 0.6 : 1.0);

    float ndv = saturate(dot(n, -rd));
    float F = 0.05 + 0.95 * pow(1.0 - ndv, 5.0);
    float3 r = reflect(rd, n);
    float3 refl;
    for (int c = 0; c < 3; c++) refl[c] = env(r, sweep, (float(c) - 1.0) * 0.004)[c];

    // Light through a rounded rim leaves by the mirrored rim on the other side, split per channel.
    float3 ne = normalize(R * float3(nl.x, nl.y, -nl.z));
    const float3 ior = float3(1.40, 1.47, 1.56);
    float3 trans;
    for (int c = 0; c < 3; c++) {
        float3 r1 = refract(rd, n, 1.0 / ior[c]);
        float3 r2 = refract(r1, -ne, ior[c]);
        if (dot(r2, r2) < 1e-4) r2 = reflect(r1, -ne);
        trans[c] = env(r2, sweep, (float(c) - 1.0) * 0.012)[c];
    }
    float3 rim = C * mix(0.55, 0.9, front) + trans * mix(float3(1.0), C, 0.5);
    Shaded s;
    s.color = mix(rim, body, face) + refl * F;
    s.base = C;
    s.face = face;
    return s;
}

struct Hit { int piece; float t; float3 p; int edgePiece; float edge; float edgeT; float3 edgeP; };

// Marches each piece in its own frame. A ray that misses keeps its nearest pass, in pixels, so the
// silhouettes come out antialiased.
static Hit trace(constant Uniforms &u, texture2d<float> field, float3 ro, float3 rd, int skip) {
    Hit h;
    h.piece = -1; h.t = 1e9; h.p = 0.0;
    h.edgePiece = -1; h.edge = 1e9; h.edgeT = 1e9; h.edgeP = 0.0;
    float pixel = 1.0 / u.view.z;
    for (int i = 0; i < 4; i++) {
        if (i == skip) continue;
        float3 rol = (u.toLocal[i] * float4(ro, 1.0)).xyz;
        float3 rdl = (u.toLocal[i] * float4(rd, 0.0)).xyz;
        float4 b = u.bounds[i];
        float2 tb = boxHit(rol, rdl, float3(b.xy, -kHalf), float3(b.zw, kHalf));
        if (tb.x > tb.y || tb.y < 0.0 || tb.x > h.t) continue;
        float t = max(tb.x, 0.0);
        float closest = 1e9; float3 closestP = rol + rdl * t; float closestT = t;
        bool hit = false;
        for (int k = 0; k < 96; k++) {
            float3 p = rol + rdl * t;
            float d = piece3(field, i, p);
            float inPixels = d / (max(t, 1e-3) * pixel);
            if (inPixels < closest) { closest = inPixels; closestP = p; closestT = t; }
            if (d < 0.0002 * t) { hit = true; break; }
            t += d * 0.9;
            if (t > tb.y || t > h.t) break;
        }
        if (hit && t < h.t) { h.t = t; h.piece = i; h.p = rol + rdl * t; }
        else if (!hit && closest < 1.0 && closestT < h.edgeT) { h.edge = closest; h.edgePiece = i; h.edgeP = closestP; h.edgeT = closestT; }
    }
    return h;
}

static float3 shoulder(float3 x) {
    float3 t = 0.97 + 0.03 * (1.0 - exp(-(x - 0.97) / 0.03));
    return select(x, t, x > 0.97);
}

static float3 toSRGB(float3 c) {
    c = saturate(c);
    return select(1.055 * pow(c, 1.0 / 2.4) - 0.055, c * 12.92, c <= 0.0031308);
}

fragment float4 mark_fragment(VOut in [[stage_in]], constant Uniforms &u [[buffer(0)]],
                              texture2d<float> field [[texture(0)]], texture2d<float> art [[texture(1)]]) {
    float2 px = in.position.xy;
    float3 ro = 0.0;
    float3 rd = normalize(float3(px.x - u.view.x * 0.5, u.view.y * 0.5 - px.y, -u.view.z));

    Hit h = trace(u, field, ro, rd, -1);
    float3 col = 0.0;
    float alpha = 0.0;
    if (h.piece >= 0) {
        Shaded s = shade(u, field, art, h.piece, h.p, rd);
        col = s.color;
        alpha = 1.0;
        // A piece still in flight lets the ones behind it show through, tinted by its own colour.
        float clear = (1.0 - u.clarity[h.piece]) * s.face;
        if (clear > 0.01) {
            Hit b = trace(u, field, ro + rd * (h.t + 0.002), rd, h.piece);
            if (b.piece >= 0) {
                float3 behind = shade(u, field, art, b.piece, b.p, rd).color;
                col = mix(col, behind * mix(float3(1.0), s.base * 1.3, 0.5), clear * 0.35);
            }
        }
        if (h.edgePiece >= 0 && h.edgeT < h.t)
            col = mix(col, shade(u, field, art, h.edgePiece, h.edgeP, rd).color, saturate(0.5 - h.edge));
    } else if (h.edgePiece >= 0) {
        col = shade(u, field, art, h.edgePiece, h.edgeP, rd).color;
        alpha = saturate(0.5 - h.edge);
    }
    return float4(toSRGB(shoulder(col)) * alpha, alpha);
}

#include <metal_stdlib>
using namespace metal;

struct Vertex { float4 position [[position]]; };

vertex Vertex cover(uint id [[vertex_id]]) {
    float2 p = float2((id << 1) & 2, id & 2);
    return { float4(p * 2 - 1, 0, 1) };
}

constexpr sampler smooth(filter::linear, address::clamp_to_edge);

struct Tint { float r, g, b, amount; };

fragment half4 tint(Vertex in [[stage_in]], texture2d<float> source [[texture(0)]], constant Tint &t [[buffer(0)]]) {
    float4 c = source.sample(smooth, in.position.xy / float2(source.get_width(), source.get_height()));
    float luma = dot(c.rgb, float3(0.299, 0.587, 0.114));
    float dark = 1 - smoothstep(0.0, 0.5, luma);
    c.rgb = mix(c.rgb, float3(t.r, t.g, t.b), dark * t.amount);
    return half4(c);
}

fragment half4 kawase(Vertex in [[stage_in]], texture2d<float> t [[texture(0)]], constant float &offset [[buffer(0)]]) {
    float2 texel = 1.0 / float2(t.get_width(), t.get_height());
    float2 uv = in.position.xy * texel, o = offset * texel;
    float4 c = t.sample(smooth, uv + float2(-o.x, -o.y)) + t.sample(smooth, uv + float2(o.x, -o.y))
             + t.sample(smooth, uv + float2(-o.x, o.y)) + t.sample(smooth, uv + o);
    return half4(c * 0.25);
}

fragment half4 blend(Vertex in [[stage_in]], texture2d<float> a [[texture(0)]], texture2d<float> b [[texture(1)]], constant float &amount [[buffer(0)]]) {
    float2 uv = in.position.xy / float2(a.get_width(), a.get_height());
    return half4(mix(a.sample(smooth, uv), b.sample(smooth, uv), amount));
}

float3 mod289(float3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
float2 mod289(float2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
float3 permute(float3 x) { return mod289(((x * 34.0) + 1.0) * x); }

float snoise(float2 v) {
    const float4 C = float4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    float2 i = floor(v + dot(v, C.yy));
    float2 x0 = v - i + dot(i, C.xx);
    float2 i1 = (x0.x > x0.y) ? float2(1.0, 0.0) : float2(0.0, 1.0);
    float4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod289(i);
    float3 p = permute(permute(i.y + float3(0.0, i1.y, 1.0)) + i.x + float3(0.0, i1.x, 1.0));
    float3 m = max(0.5 - float3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
    m = m * m;
    m = m * m;
    float3 x = 2.0 * fract(p * C.www) - 1.0;
    float3 h = abs(x) - 0.5;
    float3 ox = floor(x + 0.5);
    float3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
    float3 g;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

float hash(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}

struct Frame {
    float scaleX, scaleY, offsetX, offsetY;
    float time, blend, warp, saturation, brightness, ceiling, shadeFrom, shade, dither;
};

fragment half4 warp(Vertex in [[stage_in]], texture2d<float> from [[texture(0)]], texture2d<float> to [[texture(1)]], constant Frame &f [[buffer(0)]]) {
    // Where in the picture this pixel is; past its edges the edge carries on.
    float2 v = in.position.xy * float2(f.scaleX, f.scaleY) + float2(f.offsetX, f.offsetY);
    float2 uv = clamp(v, 0.0, 1.0);
    float t = f.time * 0.05;

    float2 centre = uv - 0.5;
    float weight = 1.0 - smoothstep(0.0, 0.7, length(centre));
    float n1 = snoise(uv * 0.35 + float2(t, t * 0.7));
    float n2 = snoise(uv * 0.35 + float2(-t * 0.8, t * 0.5) + float2(50.0, 50.0));
    float n3 = snoise(uv * 0.9 + float2(t * 1.2, -t) + float2(100.0, 0.0));
    float n4 = snoise(uv * 0.9 + float2(-t, t * 1.1) + float2(0.0, 100.0));
    float2 bend = float2(n1 * 0.65 + n3 * 0.35, n2 * 0.65 + n4 * 0.35) * weight;
    float2 p = clamp(uv + bend * f.warp, 0.0, 1.0);

    float3 c = mix(from.sample(smooth, p).rgb, to.sample(smooth, p).rgb, f.blend);
    c *= 1.0 - dot(centre, centre) * 0.3;
    float gray = dot(c, float3(0.299, 0.587, 0.114));
    c = max(mix(float3(gray), c, f.saturation), 0.0);

    // Held under the ceiling with a soft knee, in light rather than in code values (gamma 2 is near enough).
    float3 light = c * c;
    float lum = dot(light, float3(0.2126, 0.7152, 0.0722));
    float knee = f.ceiling * 0.6;
    if (lum > knee) {
        float held = knee + (f.ceiling - knee) * (1.0 - exp(-(lum - knee) / (f.ceiling - knee)));
        c *= sqrt(held / lum);
    }
    c *= f.brightness * (1.0 - f.shade * clamp((v.y - f.shadeFrom) / (1.0 - f.shadeFrom), 0.0, 1.0));
    c += (hash(float3(floor(in.position.xy), 0.0)) - 0.5) * f.dither;
    return half4(half3(c), 1.0h);
}

#include <metal_stdlib>
using namespace metal;
struct Sprite { float2 center; float radius; float kind; float4 color; };
struct Frame { float2 size; float pixel; };
struct Fragment {
    float4 position [[position]];
    float2 local;
    float radius [[flat]];
    float kind [[flat]];
    float4 color [[flat]];
};
vertex Fragment spriteVertex(uint v [[vertex_id]], uint i [[instance_id]], const device Sprite *sprites [[buffer(0)]],
                             constant Frame &frame [[buffer(1)]]) {
    Sprite s = sprites[i];
    float2 corner = float2((v & 1) ? 1.0f : -1.0f, (v & 2) ? 1.0f : -1.0f) * (s.radius + frame.pixel);
    float2 p = s.center + corner;
    Fragment out;
    out.position = float4(p.x / frame.size.x * 2 - 1, 1 - p.y / frame.size.y * 2, 0, 1);
    out.local = corner;
    out.radius = s.radius;
    out.kind = s.kind;
    out.color = s.color;
    return out;
}
fragment half4 spriteFragment(Fragment in [[stage_in]], constant Frame &frame [[buffer(0)]]) {
    float d = length(in.local);
    if (in.kind < 0.5) return half4(in.color * saturate((in.radius - d) / frame.pixel + 0.5));
    float t = d / in.radius, a = in.color.a, loud = in.kind - 1;
    float3 accent = in.color.rgb, light = mix(accent, float3(1.0f), 0.5f);
    float4 core = float4(a), inner = float4(light, 1) * 0.95 * a, outer = float4(accent, 1) * 0.32 * a * (0.6 + 0.4 * loud);
    float4 c = t < 0.16 ? mix(core, inner, t / 0.16) : t < 0.34 ? mix(inner, outer, (t - 0.16) / 0.18) : mix(outer, float4(0), saturate((t - 0.34) / 0.66));
    return half4(c);
}

#include <metal_stdlib>
using namespace metal;
struct Out { float4 position [[position]]; };
vertex Out chromaPresentVertex(uint id [[vertex_id]]) {
    float2 p = float2(float((id << 1) & 2), float(id & 2));
    return { float4(p * 2.0 - 1.0, 0.0, 1.0) };
}
fragment float4 chromaPresentFragment(Out in [[stage_in]], texture2d<float> frame [[texture(0)]]) {
    return frame.read(uint2(in.position.xy));
}
